[[[ 
const p = entity; const t = states[variables.tracker];
const s = p ? p.state : 'unknown';
const drv = t && t.attributes.driving;
let where;
if (s === 'home') where = 'Home';
else if (s !== 'not_home' && s !== 'unknown' && s !== 'unavailable') where = s;
else where = ((t && t.attributes.address) || 'Away').split(',')[0];
 return `<span class='${entity.state === 'home' ? 'dot home' : 'dot away'}'></span>` + (drv ? 'Driving' : where); ]]]
